// Flatten all text into a single continuous stream buffer
const FULL_TEXT = LOG_DATA.join('\n') + '\n\n';

const outputEl = document.getElementById('output');
const container = document.getElementById('terminal-container');
const btnPause = document.getElementById('toggle-pause');
const btnSpeed = document.getElementById('speed-up');
const btnClear = document.getElementById('clear-btn');

let charIndex = 0;
let isPaused = false;
let speedMultiplier = 1;

function renderStep() {
    if (!isPaused) {
        // Character skip logic: skip between 1 and 4 characters per animation step
        const skipAmount = Math.floor(Math.random() * 4) + 1;
        const effectiveSkip = skipAmount * speedMultiplier;

        charIndex += effectiveSkip;

        // Infinite seamless loop: wrap around continuous buffer seamlessly
        if (charIndex >= FULL_TEXT.length) {
            charIndex = charIndex % FULL_TEXT.length;
            outputEl.textContent = "";
        }

        outputEl.textContent = FULL_TEXT.substring(0, charIndex);

        // Auto-scroll to keep cursor in view
        container.scrollTop = container.scrollHeight;
    }

    // High-speed execution loop with micro-delay jitter for rapid terminal effect
    let delay = Math.random() < 0.05 ? Math.floor(Math.random() * 50) + 20 : Math.floor(Math.random() * 10) + 2;
    setTimeout(renderStep, delay);
}

// Controls
btnPause.addEventListener('click', () => {
    isPaused = !isPaused;
    btnPause.textContent = isPaused ? 'RESUME' : 'PAUSE';
});

btnSpeed.addEventListener('click', () => {
    speedMultiplier = speedMultiplier === 1 ? 3 : (speedMultiplier === 3 ? 6 : 1);
    btnSpeed.textContent = `SPEED (x${speedMultiplier})`;
});

btnClear.addEventListener('click', () => {
    charIndex = 0;
    outputEl.textContent = "";
});

// Initialize animation execution on window load
window.onload = function() {
    renderStep();
};
